 			    NXPWIFI_MGMT_FRAME_HEADER_SIZE +
@@ -3421,6 +3423,7 @@ nxpwifi_cfg80211_authenticate(struct wiphy *wiphy,
 	if (!skb) {
 		nxpwifi_dbg(adapter, ERROR,
 			    "allocate skb failed for management frame\n");
+		kfree(mgmt);
